export interface AiServiceServer extends UntypedServiceImplementation {
  /**
   * Send one assistant message; the service assembles context itself
   * (user profile via UserService, active file content via FileService)
   * rather than trusting whatever the client happens to have in memory.
   * Server-streaming: each ChatResponse carries one text delta, not the
   * full reply — the stream ending signals completion.
   */
  chat: handleServerStreamingCall<ChatRequest, ChatResponse>;
  /**
   * Grades a free-text knowledge-check answer (code_completion/debug types)
   * by judging whether it captures the correct fix/concept — not an exact
   * string match, so equivalent-but-differently-phrased answers (different
   * variable names, or an answer that states only the crucial change rather
   * than the whole surrounding snippet) are graded correct.
   */
  gradeAnswer: handleUnaryCall<GradeAnswerRequest, GradeAnswerResponse>;
  /**
   * Grades a phase submission one criterion at a time, each verdict carrying
   * the evidence for it.
   *
   * Deliberately not a chat call. Asking a model "does this submission meet the
   * goal?" produces a holistic opinion, and holistic opinions drift generous —
   * which is the failure that matters, because a false pass silently turns a
   * learning gate into a rubber stamp. Judging one narrow criterion at a time
   * and demanding a file, a line range, and a quote for every pass converts the
   * question from "is this good" into "point at where this is true", which a
   * model cannot answer by being agreeable.
   *
   * The caller decides the phase verdict by conjunction over these results;
   * this RPC never says whether the phase passed.
   */
  gradeCriteria: handleUnaryCall<GradeCriteriaRequest, GradeCriteriaResponse>;
  /**
   * Produces one "explain it back" question about work the user has already
   * completed, grounded in their actual files rather than the phase's topic in
   * the abstract — "why does your nav jump to the right section?" rather than
   * "what is an anchor link?".
   */
  generateCheckpoint: handleUnaryCall<GenerateCheckpointRequest, GenerateCheckpointResponse>;
  /**
   * Grades a free-text explanation for comprehension.
   *
   * This is the only grader in the system whose subject is the person rather
   * than the code, and it is the one an AI-era junior cannot pass by prompting:
   * the code already exists and already works, so reproducing it proves
   * nothing. Pasted code is therefore an automatic fail, not a partial credit.
   */
  gradeExplanation: handleUnaryCall<GradeExplanationRequest, GradeExplanationResponse>;
}

